mapper.select:
select daily_review_id as dailyReviewId, serve_date as serveDate, userid, user_name as userName, star_score as starScore, review_text as reviewText, regdate as regDate, updatedate as updateDate, editable from ( select row_number() over (order by r.regdate desc, r.daily_review_id desc) as rn, r.daily_review_id, r.serve_date, r.userid, m.username as user_name, r.star_score, r.review_text, r.regdate, r.updatedate, 1 as editable from tbl_daily_review r join tbl_member m on m.userid = r.userid where trunc(r.regdate) = trunc(cast(systimestamp at time zone 'Asia/Seoul' as date)) )
where rn > (#{pageNum} - 1) * #{amount} and rn <= #{pageNum} * #{amount}
order by rn
